<section x-show="activeTab==='vouchers'" x-cloak><h2>Your vouchers</h2><div class="lg-voucher-tabs">@foreach(['eligible'=>'Available','used'=>'Used','expired'=>'Unavailable'] as $key=>$label)<button @click="voucherSubTab='{{ $key }}'" :aria-pressed="voucherSubTab==='{{ $key }}'">{{ $label }} ({{ $voucherGroups['counts'][$key] }})</button>@endforeach</div>@if($couponStatus)<p role="status">{{ $couponStatus['message'] }}</p>@endif
